  socket.on("admin turn off moderator invisible", (accountId, acknowledge) => { if (!mustAdmin(socket, acknowledge)) return; const target = data.accounts[accountId]; if (!target?.moderator) return acknowledge?.({ ok: false, error: "Moderator not found." }); if (!invisibleAdmins.has(target.id)) return acknowledge?.({ ok: true, invisible: false }); updateInvisiblePresence(target, false); save(); for (const peer of io.sockets.sockets.values()) if (data.accounts[peer.data.accountId]?.admin) peer.emit("invisible requests updated"); acknowledge?.({ ok: true, invisible: false }); });
  socket.on("voice config", (acknowledge) => { const account = mustUser(socket, acknowledge); if (account) acknowledge?.({ ok: true, iceServers: voiceIceServers(account) }); });
  socket.on("voice join", (_, acknowledge) => { const account = mustUser(socket, acknowledge); if (!account) return; for (const id of [...(io.sockets.adapter.rooms.get("voice") || [])]) { const previous = io.sockets.sockets.get(id); if (!previous || previous.id === socket.id || previous.data.accountId !== account.id) continue; previous.emit("voice kicked", { message: "Voice moved to another tab." }); previous.to("voice").emit("voice participant left", previous.id); previous.leave("voice"); } const invisible = !!(account.admin || account.moderator) && invisibleAdmins.has(account.id); const peers = voiceParticipants(account); socket.join("voice"); socket.emit("voice participants", peers); for (const peerId of io.sockets.adapter.rooms.get("voice") || []) { if (peerId === socket.id) continue; const peerSocket = io.sockets.sockets.get(peerId), viewer = data.accounts[peerSocket?.data.accountId]; peerSocket?.emit("voice participant joined", voiceParticipant(socket.id, viewer)); } broadcastPresence(); broadcastHiddenAdminPresence(); acknowledge?.({ ok: true, name: shownName(account), invisible }); });
